function HARMONIC_SUBSPACE(Delta, tol):
    (lambda, Q) <- EIGH(Delta)          # ascending eigenpairs
    B <- columns Q[:, i] with |lambda_i| < tol
    return B
function HARMONIC_PROJECTION(Delta, x, tol):
    B <- HARMONIC_SUBSPACE(Delta, tol)
    return B * (transpose(B) * x)

